// RTSPAddressFlags flags used to control allocation of addresses.
type RTSPAddressFlags C.guint

const (
	// RtspAddressFlagNone: no flags.
	RtspAddressFlagNone RTSPAddressFlags = 0b0
	// RtspAddressFlagIPv4: IPv4 address.
	RtspAddressFlagIPv4 RTSPAddressFlags = 0b1
	// RtspAddressFlagIPv6: and IPv6 address.
	RtspAddressFlagIPv6 RTSPAddressFlags = 0b10
	// RtspAddressFlagEvenPort address with an even port.
	RtspAddressFlagEvenPort RTSPAddressFlags = 0b100
	// RtspAddressFlagMulticast: multicast address.
	RtspAddressFlagMulticast RTSPAddressFlags = 0b1000
	// RtspAddressFlagUnicast: unicast address.
	RtspAddressFlagUnicast RTSPAddressFlags = 0b10000
)

// String returns the names in string for RTSPAddressFlags.
func (r RTSPAddressFlags) String() string {
	if r == 0 {
		return "RTSPAddressFlags(0)"
	}

	var builder strings.Builder
	builder.Grow(131)

	for r != 0 {
		next := r & (r - 1)
		bit := r - next

		switch bit {
		case RtspAddressFlagNone:
			builder.WriteString("None|")
		case RtspAddressFlagIPv4:
			builder.WriteString("IPv4|")
		case RtspAddressFlagIPv6:
			builder.WriteString("IPv6|")
		case RtspAddressFlagEvenPort:
			builder.WriteString("EvenPort|")
		case RtspAddressFlagMulticast:
			builder.WriteString("Multicast|")
		case RtspAddressFlagUnicast:
			builder.WriteString("Unicast|")
		default:
			builder.WriteString(fmt.Sprintf("RTSPAddressFlags(0b%b)|", bit))
		}

		r = next
	}

	return strings.TrimSuffix(builder.String(), "|")
}

// Has returns true if r contains other.
func (r RTSPAddressFlags) Has(other RTSPAddressFlags) bool {
	return (r & other) == other
}

